"""
CrowdPatrol Phase 14 — Alert System Management Module.
Provides modular, per-camera isolated alert state tracking, transition logic,
telemetry-driven reason extraction, local CSV/JSON logging, and optional Firebase synchronization.
"""

import os
import csv
import json
import time
from datetime import datetime
from dataclasses import dataclass, field, asdict
from typing import Dict, List, Optional, Any, Callable
from pathlib import Path

BASE_DIR = Path(__file__).parent.parent
LOGS_DIR = BASE_DIR / "logs"


@dataclass
class AlertEvent:
    """Represents a discrete alert event generated by a camera risk transition."""
    alert_id: str
    camera_id: str
    camera_name: str
    timestamp: str
    risk_level: str          # "MEDIUM" or "HIGH"
    risk_score: float        # 0.0 to 100.0
    reason: str              # Derived human-readable reason
    status: str              # "ACTIVE", "ESCALATED", "RESOLVED", "ACKNOWLEDGED"
    details: Dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)


def derive_alert_reason(telemetry: Dict[str, Any]) -> str:
    """
    Extracts a human-readable reason string from existing telemetry sub-scores/factors
    without altering or creating new AI risk formulas.
    """
    reasons = []
    
    max_density = telemetry.get("max_density", telemetry.get("density", 0))
    growth_rate = telemetry.get("growth_rate", 0.0)
    avg_speed = telemetry.get("avg_speed", 0.0)
    anomaly_score = telemetry.get("anomaly_score", telemetry.get("anomaly", 0.0))
    risk_score = telemetry.get("risk_score", telemetry.get("combined_score", 0.0))
    
    if max_density >= 15:
        reasons.append(f"High Crowd Density ({int(max_density)} persons/cell)")
    elif max_density >= 5:
        reasons.append(f"Elevated Density ({int(max_density)} persons/cell)")
        
    if growth_rate >= 2.0:
        reasons.append(f"Rapid Crowd Influx (+{growth_rate:.1f} p/s)")
        
    if avg_speed >= 2.5:
        reasons.append(f"Abnormal Motion Speed ({avg_speed:.1f} px/f)")
        
    if anomaly_score >= 0.5:
        reasons.append(f"High Local Motion Anomaly ({anomaly_score:.2f})")

    if not reasons:
        reasons.append(f"Combined Crowd Risk (Score: {risk_score:.1f}/100)")

    return " | ".join(reasons)


class CameraAlertTracker:
    """
    State machine managing independent alert transitions for a single camera stream.
    
    Transition rules:
    - LOW -> MEDIUM: Generates a new ACTIVE MEDIUM alert.
    - LOW -> HIGH: Generates a new ACTIVE HIGH alert.
    - MEDIUM -> HIGH: Generates an ESCALATED HIGH alert.
    - HIGH -> MEDIUM: Updates state to MEDIUM (retains active alert, no new event unless cooldown).
    - MEDIUM/HIGH -> LOW: Resolves active alert (status = RESOLVED).
    - Sustained MEDIUM/HIGH: Suppresses duplicate alert events within cooldown window.
    """
    def __init__(self, camera_id: str, camera_name: str, cooldown_seconds: float = 30.0):
        self.camera_id = camera_id
        self.camera_name = camera_name
        self.cooldown_seconds = cooldown_seconds
        
        self.current_risk_level: str = "LOW"
        self.active_alert: Optional[AlertEvent] = None
        self.last_alert_time: Optional[float] = None
        self.alert_counter: int = 0

    def process_telemetry(self, telemetry: Dict[str, Any]) -> Tuple[Optional[AlertEvent], Optional[AlertEvent]]:
        """
        Evaluates frame telemetry snapshot and updates alert state.
        
        Returns:
            Tuple of (new_or_escalated_alert_event, resolved_alert_event)
        """
        new_level = str(telemetry.get("risk_level", telemetry.get("risk", "LOW"))).upper()
        if new_level not in ["LOW", "MEDIUM", "HIGH"]:
            new_level = "LOW"
            
        risk_score = float(telemetry.get("risk_score", telemetry.get("combined_score", 0.0)))
        curr_time = time.time()
        timestamp_str = telemetry.get("last_frame_time") or datetime.now().isoformat()
        
        triggered_alert: Optional[AlertEvent] = None
        resolved_alert: Optional[AlertEvent] = None
        
        # Rule 1: Transition to LOW -> Resolve any active alert
        if new_level == "LOW":
            if self.active_alert is not None:
                self.active_alert.status = "RESOLVED"
                resolved_alert = self.active_alert
                self.active_alert = None
            self.current_risk_level = "LOW"
            return None, resolved_alert
            
        # Rule 2: Escalation MEDIUM -> HIGH
        if self.current_risk_level == "MEDIUM" and new_level == "HIGH":
            self.alert_counter += 1
            alert_id = f"ALT_{self.camera_id}_{int(curr_time)}_{self.alert_counter:03d}"
            reason = derive_alert_reason(telemetry)
            
            triggered_alert = AlertEvent(
                alert_id=alert_id,
                camera_id=self.camera_id,
                camera_name=self.camera_name,
                timestamp=timestamp_str,
                risk_level="HIGH",
                risk_score=risk_score,
                reason=reason,
                status="ESCALATED",
                details=dict(telemetry)
            )
            self.active_alert = triggered_alert
            self.last_alert_time = curr_time
            self.current_risk_level = "HIGH"
            return triggered_alert, None

        # Rule 3: Initial Transition LOW -> MEDIUM or LOW -> HIGH
        if self.current_risk_level == "LOW" and new_level in ["MEDIUM", "HIGH"]:
            self.alert_counter += 1
            alert_id = f"ALT_{self.camera_id}_{int(curr_time)}_{self.alert_counter:03d}"
            reason = derive_alert_reason(telemetry)
            
            triggered_alert = AlertEvent(
                alert_id=alert_id,
                camera_id=self.camera_id,
                camera_name=self.camera_name,
                timestamp=timestamp_str,
                risk_level=new_level,
                risk_score=risk_score,
                reason=reason,
                status="ACTIVE",
                details=dict(telemetry)
            )
            self.active_alert = triggered_alert
            self.last_alert_time = curr_time
            self.current_risk_level = new_level
            return triggered_alert, None

        # Rule 4: Sustained Risk (MEDIUM -> MEDIUM or HIGH -> HIGH)
        # Check cooldown to avoid spam
        if self.current_risk_level == new_level and new_level in ["MEDIUM", "HIGH"]:
            if self.last_alert_time is None or (curr_time - self.last_alert_time) >= self.cooldown_seconds:
                # Re-trigger alert after cooldown if risk remains active
                self.alert_counter += 1
                alert_id = f"ALT_{self.camera_id}_{int(curr_time)}_{self.alert_counter:03d}"
                reason = derive_alert_reason(telemetry)
                
                triggered_alert = AlertEvent(
                    alert_id=alert_id,
                    camera_id=self.camera_id,
                    camera_name=self.camera_name,
                    timestamp=timestamp_str,
                    risk_level=new_level,
                    risk_score=risk_score,
                    reason=reason,
                    status="ACTIVE",
                    details=dict(telemetry)
                )
                self.active_alert = triggered_alert
                self.last_alert_time = curr_time
                return triggered_alert, None
            else:
                # Within cooldown: update active alert metrics without creating a new event
                if self.active_alert is not None:
                    self.active_alert.risk_score = risk_score
                    self.active_alert.details = dict(telemetry)
                return None, None

        # Rule 5: De-escalation HIGH -> MEDIUM
        if self.current_risk_level == "HIGH" and new_level == "MEDIUM":
            self.current_risk_level = "MEDIUM"
            if self.active_alert is not None:
                self.active_alert.risk_level = "MEDIUM"
                self.active_alert.risk_score = risk_score
                self.active_alert.details = dict(telemetry)
            return None, None

        self.current_risk_level = new_level
        return None, None


class AlertManager:
    """
    Central Alert Management service for CrowdPatrol multi-camera monitoring.
    Features:
    - Independent camera state tracking (CAM-01, CAM-02, etc.)
    - Local fallback persistence (CSV / JSON logging under logs/alerts.csv)
    - Optional Firebase RTDB integration
    - Event listener dispatch system
    """
    def __init__(
        self,
        cooldown_seconds: float = 30.0,
        enable_local_logging: bool = True,
        csv_path: Optional[Path] = None,
        firebase_alert_manager: Optional[Any] = None
    ):
        self.cooldown_seconds = cooldown_seconds
        self.enable_local_logging = enable_local_logging
        self.csv_path = Path(csv_path) if csv_path else LOGS_DIR / "alerts.csv"
        self.fb_manager = firebase_alert_manager
        
        self.camera_trackers: Dict[str, CameraAlertTracker] = {}
        self.active_alerts: Dict[str, AlertEvent] = {}  # key: camera_id -> active AlertEvent
        self.alert_history: List[AlertEvent] = []
        self.event_listeners: List[Callable[[AlertEvent], None]] = []

        if self.enable_local_logging:
            self._init_csv_log()

    def _init_csv_log(self):
        """Ensure local CSV log file exists with headers."""
        try:
            self.csv_path.parent.mkdir(parents=True, exist_ok=True)
            if not self.csv_path.exists():
                with open(self.csv_path, "w", newline="", encoding="utf-8") as f:
                    writer = csv.writer(f)
                    writer.writerow([
                        "alert_id", "camera_id", "camera_name", "timestamp",
                        "risk_level", "risk_score", "reason", "status"
                    ])
        except Exception as e:
            print(f"[!] AlertManager CSV init warning: {e}")

    def register_listener(self, listener: Callable[[AlertEvent], None]):
        """Register callback listener invoked whenever an alert is created/updated."""
        if listener not in self.event_listeners:
            self.event_listeners.append(listener)

    def process_camera_telemetry(self, camera_id: str, camera_name: str, telemetry: Dict[str, Any]) -> Optional[AlertEvent]:
        """
        Main entry point: processes telemetry snapshot for a specific camera stream.
        """
        if camera_id not in self.camera_trackers:
            self.camera_trackers[camera_id] = CameraAlertTracker(
                camera_id=camera_id,
                camera_name=camera_name,
                cooldown_seconds=self.cooldown_seconds
            )
            
        tracker = self.camera_trackers[camera_id]
        tracker.camera_name = camera_name  # Ensure name is updated if changed
        
        new_alert, resolved_alert = tracker.process_telemetry(telemetry)
        
        # Handle resolution
        if resolved_alert is not None:
            if camera_id in self.active_alerts:
                del self.active_alerts[camera_id]
            self.alert_history.append(resolved_alert)
            self._log_alert_locally(resolved_alert)
            self._sync_to_firebase(resolved_alert)
            self._notify_listeners(resolved_alert)
            
        # Handle new/escalated alert
        if new_alert is not None:
            self.active_alerts[camera_id] = new_alert
            self.alert_history.append(new_alert)
            self._log_alert_locally(new_alert)
            self._sync_to_firebase(new_alert)
            self._notify_listeners(new_alert)
            return new_alert

        return None

    def _log_alert_locally(self, alert: AlertEvent):
        """Append alert event to local CSV log file."""
        if not self.enable_local_logging:
            return
        try:
            with open(self.csv_path, "a", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow([
                    alert.alert_id,
                    alert.camera_id,
                    alert.camera_name,
                    alert.timestamp,
                    alert.risk_level,
                    f"{alert.risk_score:.2f}",
                    alert.reason,
                    alert.status
                ])
        except Exception as e:
            print(f"[!] Local alert CSV write failure: {e}")

    def _sync_to_firebase(self, alert: AlertEvent):
        """Syncs alert event to Firebase if FirebaseAlertManager is connected."""
        if self.fb_manager is None:
            return
        try:
            if hasattr(self.fb_manager, "store_camera_alert"):
                self.fb_manager.store_camera_alert(alert.to_dict())
            elif hasattr(self.fb_manager, "store_alert"):
                # Fallback to standard store_alert
                self.fb_manager.store_alert(
                    risk_level=alert.risk_level,
                    density=alert.details.get("max_density", 0),
                    anomaly_score=alert.details.get("anomaly_score", 0.0),
                    person_count=alert.details.get("person_count", 0),
                    combined_score=alert.risk_score
                )
        except Exception as e:
            print(f"[!] Firebase alert sync warning: {e}. Local alert operation continues.")

    def _notify_listeners(self, alert: AlertEvent):
        """Invoke registered callback functions for alert event."""
        for listener in self.event_listeners:
            try:
                listener(alert)
            except Exception as e:
                print(f"[!] Alert listener error: {e}")

    def get_active_alerts(self) -> List[AlertEvent]:
        """Returns list of currently active or escalated alerts across all cameras."""
        return list(self.active_alerts.values())

    def get_alert_history(self, limit: int = 50) -> List[AlertEvent]:
        """Returns recent alert history across all cameras."""
        return self.alert_history[-limit:]

    def get_camera_alert_status(self, camera_id: str) -> Optional[AlertEvent]:
        """Returns active alert event for a specific camera, or None if normal/low."""
        return self.active_alerts.get(camera_id)

    def clear_all(self):
        """Reset internal alert manager state."""
        self.active_alerts.clear()
        self.alert_history.clear()
        self.camera_trackers.clear()
